#!/usr/bin/env node
/**
 * Result slots for the multi-candidate experiment on an admitted judge
 * (AIJ revision, Phase 3; branch aij-revision-mclive, NOT merged until run).
 *
 *   node docs/research/aij/tools/make-mclive-slots.mjs   -> sections/generated/mclive.tex
 *
 * Every number the manuscript quotes from that experiment is a macro defined
 * here from research/effect-identity/results/multi_candidate_live.json, printed
 * in the NN.N\%~[lo--hi] form that checkPaper.js verifies (the generated file
 * lives under sections/, which the checker walks). No number is typed into the
 * prose. If the results file does not exist the script fails, and so does the
 * build: this branch cannot produce a PDF until the experiment has been run.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const aij = resolve(here, "..");
const R = resolve(aij, "..", "..", "..", "research", "effect-identity");
const src = process.env.MCLIVE_RESULTS ?? resolve(R, "results", "multi_candidate_live.json");
if (!existsSync(src)) {
  console.error(`multi_candidate_live.json not present — run the Phase 3 experiment first:\n` +
    `  node src/experiments/multiCandidateLive.js --score && node src/experiments/multiCandidateLive.js --evaluate\n` +
    `(from research/effect-identity/). This branch must not be built or merged before that.`);
  process.exit(2);
}
const r = JSON.parse(readFileSync(src, "utf8"));
if (r.status !== "COMPLETE") { console.error(`multi_candidate_live.json status is ${r.status}`); process.exit(2); }

const iv = (x) => (x && x.ci95 && x.n > 0
  ? `${(100 * x.value).toFixed(1)}\\%~[${(100 * x.ci95.lo).toFixed(1)}--${(100 * x.ci95.hi).toFixed(1)}]`
  : "n/a (no eligible units)");
const cnt = (x) => (x && x.n > 0 ? `${x.successes} of ${x.n}` : "none");
const thr = (t) => (t === "Infinity" || t === Infinity ? "$+\\infty$" : Number(t).toFixed(2));
const W = { 1: "One", 2: "Two", 5: "Five", 10: "Ten" };
const lines = [
  "%% GENERATED by tools/make-mclive-slots.mjs from results/multi_candidate_live.json — do not edit.",
  `\\newcommand{\\mclJudge}{${r.judge.replace(/_/g, "\\_")}}`,
  `\\newcommand{\\mclPoolN}{${r.calibration.poolN}}`,
  `\\newcommand{\\mclCertM}{${r.calibration.certifiableM}}`,
  `\\newcommand{\\mclUnitsDiff}{${r.units.diff}}`,
  `\\newcommand{\\mclUnitsSame}{${r.units.same}}`,
  `\\newcommand{\\mclDriftIdentical}{${iv(r.drift.identical)}}`,
  `\\newcommand{\\mclDriftIdenticalCount}{${cnt(r.drift.identical)}}`,
  `\\newcommand{\\mclDriftLarge}{${cnt(r.drift.largeChange)}}`,
  `\\newcommand{\\mclDriftSigned}{${r.drift.meanSignedDiff >= 0 ? "+" : ""}${r.drift.meanSignedDiff.toFixed(3)}}`,
  `\\newcommand{\\mclMOnePersisted}{${iv(r.drift.distinctAtM1.suppressedPersisted)}}`,
  `\\newcommand{\\mclMOneFresh}{${iv(r.drift.distinctAtM1.suppressedFresh)}}`,
  `\\newcommand{\\mclMOnePersistedCount}{${cnt(r.drift.distinctAtM1.suppressedPersisted)}}`,
  `\\newcommand{\\mclMOneFreshCount}{${cnt(r.drift.distinctAtM1.suppressedFresh)}}`,
  `\\newcommand{\\mclCrossedUp}{${r.drift.distinctAtM1.crossedUp}}`,
  `\\newcommand{\\mclCrossedDown}{${r.drift.distinctAtM1.crossedDown}}`,
];
for (const row of r.byM) {
  const w = W[row.m];
  if (!w) continue;
  lines.push(`\\newcommand{\\mclNDiff${w}}{${row.nDiffUnits}}`, `\\newcommand{\\mclNSame${w}}{${row.nSameUnits}}`);
  for (const [rule, tag] of [["uncorrected", "Unc"], ["bonferroni", "Bon"]]) {
    const x = row.rules[rule];
    lines.push(`\\newcommand{\\mclThr${tag}${w}}{${thr(row.thresholds[rule])}}`);
    lines.push(`\\newcommand{\\mclWS${tag}${w}}{${iv(x.wrongSuppression)}}`);
    lines.push(`\\newcommand{\\mclDedup${tag}${w}}{${iv(x.dedup)}}`);
    if (row.m >= 2) {
      lines.push(`\\newcommand{\\mclAttr${tag}${w}}{${iv(x.attributionErrorTiesAsErrors)}}`);
      lines.push(`\\newcommand{\\mclAttrBroken${tag}${w}}{${iv(x.attributionErrorTiesBroken)}}`);
      lines.push(`\\newcommand{\\mclAttrCount${tag}${w}}{${cnt(x.attributionErrorTiesAsErrors)}}`);
    }
  }
}
mkdirSync(resolve(aij, "sections", "generated"), { recursive: true });
writeFileSync(resolve(aij, "sections", "generated", "mclive.tex"), lines.join("\n") + "\n");
console.log(`wrote sections/generated/mclive.tex (${lines.length - 1} macros) from ${src}`);
